test:
for n, dependencies in [(5, [(4, 0), (3, 4), (2, 3), (1, 2), (3, 0)]), (6, [(1, 0), (2, 1), (3, 0), (4, 2), (4, 3), (5, 4)])]:
    order = find_installation_order(n, dependencies)
    assert sorted(order) == list(range(n))
    position = {task: index for index, task in enumerate(order)}
    assert all(position[prerequisite] < position[task] for task, prerequisite in dependencies)
